  "ht_quick3_t": "Import aus Excel oder CSV",
  "ht_quick3_d": "Schülerlisten oder Wortlisten mit wenigen Klicks importieren.",
  "ht_quick4_t": "Wo werden meine Dateien gespeichert?",
  "ht_quick4_d": "Datenordner, automatische Backups und Synchronisierung einfach erklärt.",
  "ht_quick5_t": "Noten & Abwesenheiten",
